#!/usr/bin/env node

import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { dirname, join, relative, resolve } from "node:path";

const PATCH_ID = "partner-session-results-materials-v1";
const BACKUP_ROOT = ".humanet-installer-backups";
const PACKAGE_NAME = "humanet-values";

const PAYLOAD_BASE64 = {
  "app/(protected)/t/[tenantSlug]/assessment-sessions/[sessionId]/report/[reportTemplateVersionId]/teaser/page.tsx": "",
  "features/assessment-results/api/partner-assessment-session-preview.queries.ts": "",
  "features/assessment-results/api/partner-assessment-session-materials.queries.ts": "",
  "features/assessment-results/components/assessment-session-results-page.tsx": ""
};

const COMPONENT_PATH =
  "features/assessment-results/components/assessment-session-results-page.tsx";
const MATERIALS_QUERY_PATH =
  "features/assessment-results/api/partner-assessment-session-materials.queries.ts";
const PREVIEW_QUERY_PATH =
  "features/assessment-results/api/partner-assessment-session-preview.queries.ts";
const TEASER_PAGE_PATH =
  "app/(protected)/t/[tenantSlug]/assessment-sessions/[sessionId]/report/[reportTemplateVersionId]/teaser/page.tsx";

const ASSESSMENT_PROJECTS_INDEX = "features/assessment-projects/index.ts";
const REPORT_ACCESS_INDEX = "features/report-access/index.ts";
const ASSESSMENT_RESULTS_INDEX = "features/assessment-results/index.ts";
const REPORT_BUILDER_INDEX = "features/report-builder/index.ts";
const GRANT_FORM_PATH =
  "features/assessment-projects/components/grant-report-access-to-session-form.tsx";
const PURCHASE_DIALOG_PATH =
  "features/report-access/components/tenant-report-access-purchase-dialog.tsx";
const RESULTS_ROUTE_PATH =
  "app/(protected)/t/[tenantSlug]/assessment-sessions/[sessionId]/results/page.tsx";

const REQUIRED_EXISTING_PATHS = [
  COMPONENT_PATH,
  ASSESSMENT_PROJECTS_INDEX,
  REPORT_ACCESS_INDEX,
  ASSESSMENT_RESULTS_INDEX,
  REPORT_BUILDER_INDEX,
  GRANT_FORM_PATH,
  PURCHASE_DIALOG_PATH,
  RESULTS_ROUTE_PATH,
];

const MANAGED_PATHS = [
  COMPONENT_PATH,
  MATERIALS_QUERY_PATH,
  PREVIEW_QUERY_PATH,
  TEASER_PAGE_PATH,
  ASSESSMENT_PROJECTS_INDEX,
  REPORT_ACCESS_INDEX,
  ASSESSMENT_RESULTS_INDEX,
  REPORT_BUILDER_INDEX,
  GRANT_FORM_PATH,
  PURCHASE_DIALOG_PATH,
  RESULTS_ROUTE_PATH,
];

const args = new Set(process.argv.slice(2));
const isDryRun = args.has("--dry-run");
const isRollback = args.has("--rollback");
const isFullVerification = args.has("--full");
const skipCommands = args.has("--skip-commands");

function log(message) {
  console.log(`[${PATCH_ID}] ${message}`);
}

function fail(message) {
  throw new Error(message);
}

function sha256(content) {
  return createHash("sha256").update(content).digest("hex");
}

function readJson(path) {
  return JSON.parse(readFileSync(path, "utf8"));
}

function readUtf8(root, path) {
  return readFileSync(join(root, path), "utf8");
}

function payload(path) {
  const encoded = PAYLOAD_BASE64[path];
  if (!encoded) fail(`Brak osadzonego payloadu: ${path}`);
  return Buffer.from(encoded, "base64").toString("utf8");
}

function replaceExactlyOnce(source, before, after, label) {
  const first = source.indexOf(before);
  if (first < 0) {
    fail(`Nie znaleziono oczekiwanego fragmentu: ${label}. Kod mógł się zmienić.`);
  }

  const second = source.indexOf(before, first + before.length);
  if (second >= 0) {
    fail(`Fragment występuje więcej niż raz: ${label}.`);
  }

  return source.slice(0, first) + after + source.slice(first + before.length);
}

function appendExport(source, exportLine) {
  if (source.includes(exportLine)) return source;
  return source.replace(/\s*$/, "") + `\n${exportLine}\n`;
}

function ensureProjectRoot(root) {
  const packagePath = join(root, "package.json");
  if (!existsSync(packagePath)) {
    fail("Uruchom instalator w katalogu głównym repozytorium HUMANET VALUES.");
  }

  const pkg = readJson(packagePath);
  if (pkg.name !== PACKAGE_NAME) {
    fail(`Nieoczekiwany projekt: package.json name=${JSON.stringify(pkg.name)}.`);
  }

  for (const path of REQUIRED_EXISTING_PATHS) {
    const absolute = join(root, path);
    if (!existsSync(absolute) || !statSync(absolute).isFile()) {
      fail(`Brak wymaganego pliku: ${path}`);
    }
  }
}

function patchComponent(source) {
  const expected = payload(COMPONENT_PATH);
  if (source === expected) return source;

  const legacyMarkers = [
    'title="Wyniki wymiarów"',
    "getAssessmentSessionResults",
    "RecalculateAssessmentSessionScoresForm",
    "Uwagi",
  ];

  for (const marker of legacyMarkers) {
    if (!source.includes(marker)) {
      fail(
        `Nie rozpoznano dotychczasowego widoku wyników: brak ${JSON.stringify(marker)}.`,
      );
    }
  }

  return expected;
}

function patchAssessmentProjectsIndex(source) {
  return appendExport(
    source,
    'export { GrantReportAccessToSessionForm } from "./components/grant-report-access-to-session-form";',
  );
}

function patchReportAccessIndex(source) {
  return appendExport(
    source,
    'export { TenantReportAccessPurchaseDialog } from "./components/tenant-report-access-purchase-dialog";',
  );
}

function patchAssessmentResultsIndex(source) {
  let result = appendExport(
    source,
    'export * from "./api/partner-assessment-session-materials.queries";',
  );
  result = appendExport(
    result,
    'export * from "./api/partner-assessment-session-preview.queries";',
  );
  return result;
}


function patchReportBuilderIndex(source) {
  return appendExport(
    source,
    'export { resolveReportPreviewConfig } from "./lib/report-preview-config";',
  );
}

function patchGrantForm(source) {
  if (
    source.includes('import { useRouter } from "next/navigation";') &&
    source.includes("router.refresh();")
  ) {
    return source;
  }

  let result = replaceExactlyOnce(
    source,
    'import { useActionState, useMemo, useState } from "react";',
    'import { useActionState, useEffect, useMemo, useState } from "react";\nimport { useRouter } from "next/navigation";',
    "importy formularza nadawania dostępu",
  );

  result = replaceExactlyOnce(
    result,
    `export function GrantReportAccessToSessionForm({
  tenantSlug,
  sessionId,
  products,
  session,
}: GrantReportAccessToSessionFormProps) {
  const [state, formAction, isPending] = useActionState(`,
    `export function GrantReportAccessToSessionForm({
  tenantSlug,
  sessionId,
  products,
  session,
}: GrantReportAccessToSessionFormProps) {
  const router = useRouter();

  const [state, formAction, isPending] = useActionState(`,
    "router formularza nadawania dostępu",
  );

  result = replaceExactlyOnce(
    result,
    `  const [state, formAction, isPending] = useActionState(
    grantReportAccessToCompletedSessionAction,
    initialState,
  );

  const availableProducts = useMemo(`,
    `  const [state, formAction, isPending] = useActionState(
    grantReportAccessToCompletedSessionAction,
    initialState,
  );

  useEffect(() => {
    if (state.status === "success" && !isPending) {
      router.refresh();
    }
  }, [isPending, router, state.status]);

  const availableProducts = useMemo(`,
    "odświeżenie po nadaniu dostępu",
  );

  return result;
}

function patchPurchaseDialog(source) {
  if (
    source.includes('import { useRouter } from "next/navigation";') &&
    source.includes("setOpen(false);\n      router.refresh();")
  ) {
    return source;
  }

  let result = source;

  if (!result.includes('import { useRouter } from "next/navigation";')) {
    result = replaceExactlyOnce(
      result,
      '"use client";\nimport { ApplyDiscountCodeForm }',
      '"use client";\nimport { useRouter } from "next/navigation";\nimport { ApplyDiscountCodeForm }',
      "import routera w dialogu zakupu",
    );
  }

  result = replaceExactlyOnce(
    result,
    `export function TenantReportAccessPurchaseDialog({
  tenantSlug,
  products,
  billingProfile,
}: TenantReportAccessPurchaseDialogProps) {


    const [state, formAction, isPending] = useActionState(`,
    `export function TenantReportAccessPurchaseDialog({
  tenantSlug,
  products,
  billingProfile,
}: TenantReportAccessPurchaseDialogProps) {
  const router = useRouter();

  const [state, formAction, isPending] = useActionState(`,
    "router dialogu zakupu",
  );

  result = replaceExactlyOnce(
    result,
    `  useEffect(() => {
    if (state.status === "success" && !isPending) {
      setOpen(false);
    }
  }, [state.status, isPending]);`,
    `  useEffect(() => {
    if (state.status === "success" && !isPending) {
      setOpen(false);
      router.refresh();
    }
  }, [state.status, isPending, router]);`,
    "odświeżenie po zakupie dostępu",
  );

  return result;
}

function patchResultsRoute(source) {
  if (!source.includes('console.log("Assessment session results route params"')) {
    return source;
  }

  return replaceExactlyOnce(
    source,
    `  const { tenantSlug, sessionId } = await params;
console.log("Assessment session results route params", {
  tenantSlug,
  sessionId,
});
  if (!tenantSlug || !sessionId) {`,
    `  const { tenantSlug, sessionId } = await params;

  if (!tenantSlug || !sessionId) {`,
    "techniczny log parametrów sesji",
  );
}

function plan(root) {
  const original = new Map();
  const planned = new Map();

  for (const path of MANAGED_PATHS) {
    const absolute = join(root, path);
    original.set(path, existsSync(absolute) ? readFileSync(absolute, "utf8") : null);
  }

  planned.set(COMPONENT_PATH, patchComponent(original.get(COMPONENT_PATH)));
  planned.set(MATERIALS_QUERY_PATH, payload(MATERIALS_QUERY_PATH));
  planned.set(PREVIEW_QUERY_PATH, payload(PREVIEW_QUERY_PATH));
  planned.set(TEASER_PAGE_PATH, payload(TEASER_PAGE_PATH));
  planned.set(
    ASSESSMENT_PROJECTS_INDEX,
    patchAssessmentProjectsIndex(original.get(ASSESSMENT_PROJECTS_INDEX)),
  );
  planned.set(
    REPORT_ACCESS_INDEX,
    patchReportAccessIndex(original.get(REPORT_ACCESS_INDEX)),
  );
  planned.set(
    ASSESSMENT_RESULTS_INDEX,
    patchAssessmentResultsIndex(original.get(ASSESSMENT_RESULTS_INDEX)),
  );
  planned.set(
    REPORT_BUILDER_INDEX,
    patchReportBuilderIndex(original.get(REPORT_BUILDER_INDEX)),
  );
  planned.set(GRANT_FORM_PATH, patchGrantForm(original.get(GRANT_FORM_PATH)));
  planned.set(
    PURCHASE_DIALOG_PATH,
    patchPurchaseDialog(original.get(PURCHASE_DIALOG_PATH)),
  );
  planned.set(RESULTS_ROUTE_PATH, patchResultsRoute(original.get(RESULTS_ROUTE_PATH)));

  for (const path of [MATERIALS_QUERY_PATH, PREVIEW_QUERY_PATH, TEASER_PAGE_PATH]) {
    const before = original.get(path);
    const after = planned.get(path);
    if (before !== null && before !== after) {
      fail(
        `Plik ${path} już istnieje, ale ma inną zawartość. Nie nadpisuję obcej implementacji.`,
      );
    }
  }

  const changedPaths = MANAGED_PATHS.filter(
    (path) => original.get(path) !== planned.get(path),
  );

  return { original, planned, changedPaths };
}

function staticVerification(files) {
  const component = files.get(COMPONENT_PATH);
  for (const forbidden of [
    'title="Wyniki wymiarów"',
    "RecalculateAssessmentSessionScoresForm",
    "getAssessmentSessionResults",
    ">Uwagi<",
  ]) {
    if (component.includes(forbidden)) {
      fail(`Widok nadal zawiera techniczny element: ${forbidden}`);
    }
  }

  for (const required of [
    "Podsumowania i raporty",
    "GrantReportAccessToSessionForm",
    "TenantReportAccessPurchaseDialog",
    "Bezpłatne podsumowanie",
    "Wykorzystaj dostęp z puli",
    "Brak wolnych dostępów",
  ]) {
    if (!component.includes(required)) {
      fail(`Weryfikacja widoku: brak ${JSON.stringify(required)}.`);
    }
  }

  const materialsQuery = files.get(MATERIALS_QUERY_PATH);
  for (const required of [
    "normativeProfileSessionLinks",
    "reportAccessGrants",
    "reportAccessCodes",
    'sessionRow.sessionStatus === "completed"',
    'ctx.permissions.includes("assessment_project:update")',
  ]) {
    if (!materialsQuery.includes(required)) {
      fail(`Weryfikacja query materiałów: brak ${JSON.stringify(required)}.`);
    }
  }

  for (const forbidden of ["assessmentDimensionScores", "assessmentResponses"]) {
    if (materialsQuery.includes(forbidden)) {
      fail(`Query partnera nie powinno pobierać technicznych wyników: ${forbidden}.`);
    }
  }

  const previewQuery = files.get(PREVIEW_QUERY_PATH);
  for (const required of [
    'overview.session.status !== "completed"',
    "overview.normativeDataAvailable",
    'action: "report_preview_viewed"',
    '"tenant_partner_normative_summary"',
  ]) {
    if (!previewQuery.includes(required)) {
      fail(`Weryfikacja darmowego podsumowania: brak ${JSON.stringify(required)}.`);
    }
  }

  const teaserPage = files.get(TEASER_PAGE_PATH);
  for (const required of [
    'mode: "personal_teaser"',
    "getPartnerAssessmentSessionPreview",
    "Sam profil normatywny respondenta nie jest tutaj",
  ]) {
    if (!teaserPage.includes(required)) {
      fail(`Weryfikacja strony podsumowania: brak ${JSON.stringify(required)}.`);
    }
  }

  if (!files.get(ASSESSMENT_PROJECTS_INDEX).includes("GrantReportAccessToSessionForm")) {
    fail("Brak publicznego eksportu formularza nadawania dostępu.");
  }
  if (!files.get(REPORT_ACCESS_INDEX).includes("TenantReportAccessPurchaseDialog")) {
    fail("Brak publicznego eksportu dialogu zakupu.");
  }
  if (!files.get(ASSESSMENT_RESULTS_INDEX).includes("partner-assessment-session-preview.queries")) {
    fail("Brak publicznego eksportu query podsumowania.");
  }
  if (!files.get(REPORT_BUILDER_INDEX).includes("resolveReportPreviewConfig")) {
    fail("Brak publicznego eksportu konfiguracji podsumowania raportu.");
  }
  if (!files.get(GRANT_FORM_PATH).includes("router.refresh();")) {
    fail("Formularz nadawania dostępu nie odświeża widoku po sukcesie.");
  }
  if (!files.get(PURCHASE_DIALOG_PATH).includes("setOpen(false);\n      router.refresh();")) {
    fail("Dialog zakupu nie odświeża widoku po sukcesie.");
  }
  if (files.get(RESULTS_ROUTE_PATH).includes("Assessment session results route params")) {
    fail("Trasa nadal loguje techniczne identyfikatory sesji.");
  }
}

function writePlannedFiles(root, planned, changedPaths) {
  for (const path of changedPaths) {
    const absolute = join(root, path);
    mkdirSync(dirname(absolute), { recursive: true });
    writeFileSync(absolute, planned.get(path), "utf8");
  }
}

function currentFiles(root) {
  const files = new Map();
  for (const path of MANAGED_PATHS) {
    const absolute = join(root, path);
    files.set(path, existsSync(absolute) ? readFileSync(absolute, "utf8") : null);
  }
  return files;
}

function makeBackup(root, original, changedPaths) {
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const backupDir = join(root, BACKUP_ROOT, `${PATCH_ID}-${stamp}`);
  const entries = [];

  for (const path of changedPaths) {
    const before = original.get(path);
    const existed = before !== null;
    const backupPath = join(backupDir, "files", path);

    if (existed) {
      mkdirSync(dirname(backupPath), { recursive: true });
      writeFileSync(backupPath, before, "utf8");
    }

    entries.push({
      path,
      existed,
      originalSha256: existed ? sha256(before) : null,
    });
  }

  mkdirSync(backupDir, { recursive: true });
  writeFileSync(
    join(backupDir, "manifest.json"),
    JSON.stringify(
      {
        patchId: PATCH_ID,
        createdAt: new Date().toISOString(),
        files: entries,
      },
      null,
      2,
    ) + "\n",
    "utf8",
  );

  return backupDir;
}

function restoreFromOriginal(root, original, changedPaths) {
  for (const path of [...changedPaths].reverse()) {
    const absolute = join(root, path);
    const before = original.get(path);

    if (before === null) {
      rmSync(absolute, { force: true });
    } else {
      mkdirSync(dirname(absolute), { recursive: true });
      writeFileSync(absolute, before, "utf8");
    }
  }
}

function listBackups(root) {
  const directory = join(root, BACKUP_ROOT);
  if (!existsSync(directory)) return [];

  return readdirSync(directory)
    .filter((name) => name.startsWith(`${PATCH_ID}-`))
    .map((name) => join(directory, name))
    .filter((path) => statSync(path).isDirectory())
    .sort()
    .reverse();
}

function rollback(root) {
  const backups = listBackups(root);
  if (backups.length === 0) {
    fail(`Nie znaleziono backupu dla ${PATCH_ID}.`);
  }

  const backupDir = backups[0];
  const manifestPath = join(backupDir, "manifest.json");
  if (!existsSync(manifestPath)) fail(`Backup jest niekompletny: ${backupDir}`);

  const manifest = readJson(manifestPath);
  if (manifest.patchId !== PATCH_ID || !Array.isArray(manifest.files)) {
    fail(`Nieprawidłowy manifest backupu: ${backupDir}`);
  }

  for (const entry of [...manifest.files].reverse()) {
    const absolute = join(root, entry.path);

    if (!entry.existed) {
      rmSync(absolute, { force: true });
      continue;
    }

    const backupPath = join(backupDir, "files", entry.path);
    if (!existsSync(backupPath)) fail(`Brak pliku backupu: ${entry.path}`);
    const content = readFileSync(backupPath, "utf8");

    if (sha256(content) !== entry.originalSha256) {
      fail(`Nieprawidłowa suma SHA-256 backupu: ${entry.path}`);
    }

    mkdirSync(dirname(absolute), { recursive: true });
    writeFileSync(absolute, content, "utf8");

    if (sha256(readFileSync(absolute, "utf8")) !== entry.originalSha256) {
      fail(`Rollback nie przywrócił poprawnie: ${entry.path}`);
    }
  }

  log(`Przywrócono pliki z backupu: ${relative(root, backupDir)}`);
}

function commandOutput(value) {
  if (typeof value === "string") return value;
  if (Buffer.isBuffer(value)) return value.toString("utf8");
  return "";
}

function captureCommand(root, command, commandArgs, label) {
  log(`Sprawdzam: ${label}`);

  try {
    const stdout = execFileSync(command, commandArgs, {
      cwd: root,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
      env: { ...process.env, FORCE_COLOR: "0", NO_COLOR: "1" },
    });
    return { ok: true, output: commandOutput(stdout).trim(), status: 0 };
  } catch (error) {
    const stdout = error && typeof error === "object" && "stdout" in error
      ? commandOutput(error.stdout)
      : "";
    const stderr = error && typeof error === "object" && "stderr" in error
      ? commandOutput(error.stderr)
      : "";
    const status = error && typeof error === "object" && "status" in error
      ? Number(error.status ?? 1)
      : 1;
    return {
      ok: false,
      output: [stdout, stderr].filter(Boolean).join("\n").trim(),
      status: Number.isFinite(status) ? status : 1,
    };
  }
}

function normalizeOutput(output, root) {
  return output
    .replaceAll(`${root}/`, "")
    .replaceAll(`${root}\\`, "")
    .replace(/\x1B\[[0-?]*[ -\/]*[@-~]/g, "")
    .replace(/\r/g, "")
    .trim();
}

function parseTypeScriptDiagnostics(output, root) {
  const diagnostics = new Map();
  const normalized = normalizeOutput(output, root);

  for (const line of normalized.split("\n")) {
    const compactMatch = line.match(/^(.*)\((\d+),(\d+)\): error (TS\d+): (.*)$/);
    const prettyMatch = line.match(/^(.*):(\d+):(\d+)\s+-\s+error (TS\d+):\s+(.*)$/);
    const match = compactMatch ?? prettyMatch;
    if (!match) continue;
    const [, file, , , code, message] = match;
    diagnostics.set(`${file.trim()}|${code}|${message.trim()}`, line.trim());
  }

  return diagnostics;
}

function parseFailureSignatures(output, root) {
  const normalized = normalizeOutput(output, root);
  const signatures = new Map();

  for (const originalLine of normalized.split("\n")) {
    const line = originalLine.trim();
    if (!line) continue;

    const relevant =
      /(^|\s)(error|failed|failure|fail|type error|module not found|cannot find module|command failed)(\s|:|$)/i.test(line) ||
      /\bTS\d+\b/.test(line) || /^(FAIL|⨯|×|✖)/.test(line);
    if (!relevant) continue;

    const signature = line
      .replace(/\b\d+(?:\.\d+)?\s*(ms|s|min)\b/gi, "<duration>")
      .replace(/\b\d+(?:\.\d+)?\s*(KB|MB|GB)\b/gi, "<size>")
      .replace(/:\d+:\d+/g, ":<line>:<column>")
      .replace(/\(\d+,\d+\)/g, "(<line>,<column>)");
    signatures.set(signature, line);
  }

  return signatures;
}

function printExistingFailures(label, result, root) {
  const excerpt = normalizeOutput(result.output, root).split("\n").slice(0, 40).join("\n");
  log(
    `UWAGA: ${label} ma błędy istniejące już przed instalacją. ` +
      "Nie blokują zmiany, ponieważ po instalacji nie pojawiły się nowe diagnostyki.",
  );
  if (excerpt) console.log(`\n--- istniejące błędy: ${label} ---\n${excerpt}\n--- koniec ---\n`);
}

function verifyTypeScriptAgainstBaseline(root, localTsc, baseline) {
  const after = captureCommand(
    root,
    localTsc,
    ["--noEmit", "--pretty", "false"],
    "TypeScript po zmianie (tsc --noEmit)",
  );

  if (after.ok) {
    log("TypeScript po zmianie: bez błędów.");
    return;
  }

  if (baseline.ok) {
    console.error(normalizeOutput(after.output, root));
    fail("Zmiana wprowadziła błędy TypeScript.");
  }

  const beforeDiagnostics = parseTypeScriptDiagnostics(baseline.output, root);
  const afterDiagnostics = parseTypeScriptDiagnostics(after.output, root);
  const newDiagnostics = [...afterDiagnostics.entries()].filter(
    ([signature]) => !beforeDiagnostics.has(signature),
  );

  if (newDiagnostics.length > 0) {
    console.error(
      `\nNowe błędy TypeScript po zmianie:\n${newDiagnostics.map(([, line]) => line).join("\n")}`,
    );
    fail("Zmiana wprowadziła nowe błędy TypeScript.");
  }

  if (afterDiagnostics.size === 0) {
    const beforeNormalized = normalizeOutput(baseline.output, root);
    const afterNormalized = normalizeOutput(after.output, root);
    if (beforeNormalized !== afterNormalized) {
      console.error(afterNormalized);
      fail("TypeScript zakończył się błędem, którego nie można bezpiecznie porównać.");
    }
  }

  printExistingFailures("TypeScript", after, root);
}

function verifyGenericCommandAgainstBaseline({ root, command, commandArgs, label, baseline }) {
  const after = captureCommand(root, command, commandArgs, `${label} po zmianie`);
  if (after.ok) {
    log(`${label} po zmianie: powodzenie.`);
    return;
  }
  if (baseline.ok) {
    console.error(normalizeOutput(after.output, root));
    fail(`${label} nie przechodzi po zmianie.`);
  }

  const beforeSignatures = parseFailureSignatures(baseline.output, root);
  const afterSignatures = parseFailureSignatures(after.output, root);
  const newSignatures = [...afterSignatures.entries()].filter(
    ([signature]) => !beforeSignatures.has(signature),
  );
  if (newSignatures.length > 0) {
    console.error(`\nNowe sygnatury błędów (${label}):\n${newSignatures.map(([, line]) => line).join("\n")}`);
    fail(`${label} wykazał nowe błędy po zmianie.`);
  }
  if (beforeSignatures.size === 0) {
    const beforeNormalized = normalizeOutput(baseline.output, root);
    const afterNormalized = normalizeOutput(after.output, root);
    if (beforeNormalized !== afterNormalized) {
      console.error(afterNormalized);
      fail(`${label} zakończył się błędem, którego nie można bezpiecznie porównać.`);
    }
  }
  printExistingFailures(label, after, root);
}

function resolveVerificationCommands(root) {
  if (skipCommands) {
    log("Pominięto komendy weryfikacyjne (--skip-commands).");
    return null;
  }

  const localTsc = join(
    root,
    "node_modules",
    ".bin",
    process.platform === "win32" ? "tsc.cmd" : "tsc",
  );
  if (!existsSync(localTsc)) {
    log(
      "UWAGA: brak node_modules/.bin/tsc — wykonana zostanie wyłącznie weryfikacja statyczna.",
    );
    return null;
  }

  return { localTsc, npm: process.platform === "win32" ? "npm.cmd" : "npm" };
}

function captureBaseline(root, commands) {
  if (!commands) return null;

  const baseline = {
    typescript: captureCommand(
      root,
      commands.localTsc,
      ["--noEmit", "--pretty", "false"],
      "stan początkowy TypeScript",
    ),
    tests: null,
    build: null,
  };

  if (isFullVerification) {
    baseline.tests = captureCommand(root, commands.npm, ["test"], "stan początkowy testów Vitest");
    baseline.build = captureCommand(root, commands.npm, ["run", "build"], "stan początkowy buildu produkcyjnego");
  }

  return baseline;
}

function commandVerification(root, commands, baseline) {
  if (!commands || !baseline) return;
  verifyTypeScriptAgainstBaseline(root, commands.localTsc, baseline.typescript);
  if (isFullVerification) {
    verifyGenericCommandAgainstBaseline({
      root,
      command: commands.npm,
      commandArgs: ["test"],
      label: "Testy Vitest",
      baseline: baseline.tests,
    });
    verifyGenericCommandAgainstBaseline({
      root,
      command: commands.npm,
      commandArgs: ["run", "build"],
      label: "Build produkcyjny Next.js",
      baseline: baseline.build,
    });
  }
}

function main() {
  const root = resolve(process.cwd());
  ensureProjectRoot(root);

  if (isRollback) {
    rollback(root);
    return;
  }

  const { original, planned, changedPaths } = plan(root);
  staticVerification(planned);

  log(`Pliki zarządzane: ${MANAGED_PATHS.length}.`);
  log(`Pliki wymagające zmiany: ${changedPaths.length}.`);
  for (const path of changedPaths) log(`  - ${path}`);

  if (isDryRun) {
    log(changedPaths.length === 0 ? "Dry run: zmiana jest już zainstalowana." : "Dry run zakończony poprawnie. Nie zapisano plików.");
    return;
  }

  const commands = resolveVerificationCommands(root);

  if (changedPaths.length === 0) {
    staticVerification(currentFiles(root));
    log("Zmiana jest już zainstalowana; nie wykonano ponownego zapisu ani rollbacku.");
    return;
  }

  const baseline = captureBaseline(root, commands);
  const backupDir = makeBackup(root, original, changedPaths);
  log(`Backup: ${relative(root, backupDir)}`);

  try {
    writePlannedFiles(root, planned, changedPaths);
    const installed = currentFiles(root);
    staticVerification(installed);
    commandVerification(root, commands, baseline);

    log("Instalacja zakończona.");
    for (const path of changedPaths) {
      const content = installed.get(path);
      log(`SHA-256 ${path}: ${content === null ? "<brak>" : sha256(content)}`);
    }
  } catch (error) {
    restoreFromOriginal(root, original, changedPaths);
    log(
      "Błąd wprowadzony przez instalację lub niejednoznaczna weryfikacja — " +
        "automatycznie przywrócono stan sprzed zmiany.",
    );
    throw error;
  }
}

try {
  main();
} catch (error) {
  console.error(`\n[${PATCH_ID}] BŁĄD: ${error instanceof Error ? error.message : String(error)}`);
  process.exitCode = 1;
}
